pub fn velocity_blend_direction(world_velocity: Vec3, character_rotation: Quat) -> Vec3 {
    let local = character_rotation.inverse() * world_velocity;
    if local.length_squared() > 1e-12 {
        local / local.abs().element_sum()
    } else {
        Vec3::ZERO
    }
}

